using System;using System.Threading;using System.Threading.Tasks;using IslandIntegrated;using IslandMedia;
class LyricsRefreshTests {static void Check(bool x,string m){if(!x)throw new Exception(m);Console.WriteLine("PASS "+m);} static int Main(){
var now=new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero);int calls=0,status=404;var song=new Snapshot{SourceId="cloudmusic.exe",Title="Fixture song",Artist="Fixture artist",DurationSeconds=120};
var source=new LrclibSource(true,(u,t)=>{calls++;return Task.FromResult(new LyricHttpResult{Status=status,RetryAfter="120",Body="[{\"id\":1,\"trackName\":\"Fixture song\",\"artistName\":\"Fixture artist\",\"duration\":120,\"syncedLyrics\":\"[00:01.00]fixture\"}]"});},()=>now);
Check(source.ReadAsync(song,CancellationToken.None).Result.State=="not-found"&&calls==1,"initial not-found recorded");status=200;Check(source.ReadAsync(song,CancellationToken.None).Result.State=="not-found"&&calls==1,"automatic read reuses cache");now=now.AddSeconds(1);Check(source.ReadAsync(song,CancellationToken.None,true).Result.State=="ready"&&calls==2,"manual refresh bypasses cached miss");now=now.AddSeconds(1);status=429;Check(source.ReadAsync(song,CancellationToken.None,true).Result.State=="rate-limited"&&calls==3,"rate limit recorded");now=now.AddSeconds(1);Check(source.ReadAsync(song,CancellationToken.None,true).Result.State=="rate-limited"&&calls==3,"manual refresh respects server backoff");now=now.AddSeconds(121);status=200;Check(source.ReadAsync(song,CancellationToken.None,true).Result.State=="ready"&&calls==4,"manual refresh resumes after backoff");source.Dispose();return 0;}}
